ExpressionBuilder = {
  init: function(app, container, config, callback) {
    config = config || {};
    config.expression = config.expression || '';
    ExpressionBuilder.build(container, config, callback);
  },

  getMetaFor: function(serverTypeName) {
    return window.knownTypes.map(ctx => ctx.Types).reduce((a, b) => a.concat(b)).filter(t => t.ServerTypeName === serverTypeName)[0];
  },

  build: function(container, config, callback) {
    var args = [];
    if (config.args) {
      for (var name in config.args) {
        var meta = ExpressionBuilder.getMetaFor(config.args[name]);
        if (!meta) continue;
        args.push('<div class="metaType tip">' + html.encode(meta.ServerTypeName) + '<ul class="fieldList metaList tooltiptext">' + ExpressionBuilder.getProps(meta) + ExpressionBuilder.getMethods(meta) + '</ul></div> ' + html.encode(name));
      }
    }

    var codeHost = $('[name=code]', container)[0];
    if (!codeHost) {
      throw new Error('The expression code editor host was not rendered.');
    }

    var editor = new CSharpMonacoEditor(codeHost, {
      fixedOverflowWidgets: true,
      automaticLayout: true,
      code: config.expression.trim() + '\n\n'
    });
    editor.init();
    $('[name=in]', container).html('(' + args.join(', ') + ') =&gt; ');
    $('[name=expressionBuilderForm]', container).off('submit.expressionBuilder').on('submit.expressionBuilder', function(e) {
      e.preventDefault();
      callback(editor.getValue());
    });
  },

  getProps: function(meta) {
    return (meta.Properties || []).map(function(property) {
      var typeInfo = property.ServerTypeName.split('.');
      return '<li class="meta"><span class="k-icon k-i-arrow-60-right"></span><div class="metaType">' + html.encode(typeInfo[typeInfo.length - 1]) + '</div> ' + html.encode(property.Name) + '</li>';
    }).join('');
  },

  getMethods: function(meta) {
    return (meta.Methods || []).map(function(method) {
      var typeInfo = method.Returns.ServerTypeName.split('.');
      return '<li class="meta"><span class="k-icon k-i-drag-and-drop"></span><div class="metaType">' + html.encode(typeInfo[typeInfo.length - 1]) + '</div> ' + html.encode(method.Name) + '(' + ExpressionBuilder.getParams(method) + ')</li>';
    }).join('');
  },

  getParams: function(method) {
    return (method.Parameters || []).map(parameter => '<span class="paramType">' + html.encode(parameter.ServerTypeName) + '</span> ' + html.encode(parameter.Name || parameter.name)).join(', ');
  }
}
